import Foundation

enum AppLocalizable {
    static func string(_ key: String, language: AppLanguage) -> String {
        if let value = table(for: language)[key] {
            return value
        }
        if language != .english, let value = english[key] {
            return value
        }
        return key
    }

    /// A trial string with its day count filled in: `{n}` is the number of days, `{dayWord}`
    /// the unit for the languages that inflect it with the number (Russian, Czech, Slovak).
    /// The store decides the trial length, so no string may carry the number itself.
    static func trialString(_ key: String, days: Int, language: AppLanguage) -> String {
        string(key, language: language)
            .replacingOccurrences(of: "{n}", with: String(days))
            .replacingOccurrences(of: "{dayWord}", with: dayWord(days, language: language))
    }

    /// « 27 ans », « 1 an », « 3 года » : le mot « an(s) » accordé au nombre, d'après les
    /// clés `onboardingV2.yearsGrid.years.<forme>` (`one`, `two`, `few`, `many`) de la
    /// langue ; une forme absente retombe sur `many`.
    static func yearsString(_ n: Int, language: AppLanguage) -> String {
        let form: String
        switch language {
        case .russian, .serbian, .croatian:
            let mod10 = n % 10, mod100 = n % 100
            if mod10 == 1 && mod100 != 11 { form = "one" }
            else if (2...4).contains(mod10) && !(12...14).contains(mod100) { form = "few" }
            else { form = "many" }
        case .polish:
            let mod10 = n % 10, mod100 = n % 100
            if n == 1 { form = "one" }
            else if (2...4).contains(mod10) && !(12...14).contains(mod100) { form = "few" }
            else { form = "many" }
        case .czech, .slovak:
            form = n == 1 ? "one" : ((2...4).contains(n) ? "few" : "many")
        case .slovenian:
            switch n % 100 {
            case 1: form = "one"
            case 2: form = "two"
            case 3, 4: form = "few"
            default: form = "many"
            }
        case .romanian:
            form = n == 1 ? "one" : (n < 20 ? "few" : "many")
        case .arabic:
            form = n == 1 ? "one" : (n == 2 ? "two" : ((3...10).contains(n) ? "few" : "many"))
        case .hebrew:
            form = n == 1 ? "one" : (n == 2 ? "two" : "many")
        default:
            form = n == 1 ? "one" : "many"
        }
        let key = "onboardingV2.yearsGrid.years.\(form)"
        var pattern = string(key, language: language)
        if pattern == key {
            pattern = string("onboardingV2.yearsGrid.years.many", language: language)
        }
        return String(format: pattern, n)
    }

    private static func dayWord(_ n: Int, language: AppLanguage) -> String {
        switch language {
        case .russian:
            let mod10 = n % 10, mod100 = n % 100
            if mod10 == 1 && mod100 != 11 { return "день" }
            if (2...4).contains(mod10) && !(12...14).contains(mod100) { return "дня" }
            return "дней"
        case .czech:
            return n == 1 ? "den" : ((2...4).contains(n) ? "dny" : "dní")
        case .slovak:
            return n == 1 ? "deň" : ((2...4).contains(n) ? "dni" : "dní")
        default:
            return ""
        }
    }

    private static func table(for language: AppLanguage) -> [String: String] {
        switch language {
        case .french: french
        case .english: english
        case .spanish: spanish
        case .german: german
        case .portuguese: portuguese
        case .portuguesePortugal: portuguesePortugal
        case .italian: italian
        case .turkish: turkish
        case .polish: polish
        case .romanian: romanian
        case .dutch: dutch
        case .greek: greek
        case .swedish: swedish
        case .hungarian: hungarian
        case .bulgarian: bulgarian
        case .czech: czech
        case .danish: danish
        case .norwegian: norwegian
        case .russian: russian
        case .croatian: croatian
        case .slovenian: slovenian
        case .slovak: slovak
        case .serbian: serbian
        case .arabic: arabic
        case .hebrew: hebrew
        case .finnish: finnish
        case .estonian: estonian
        }
    }

